@Service
public class OrderService {
    private final PaymentGateway paymentGateway;     // constructor-injected (required)
    private NotificationService notificationService; // setter-injected (optional)

    @Autowired
    private AuditLogger auditLogger;                  // field-injected (discouraged)

    // Constructor injection - recommended for required dependencies.
    // With a single constructor, Spring wires it without @Autowired (since 4.3).
    public OrderService(PaymentGateway paymentGateway) {
        this.paymentGateway = paymentGateway;
    }

    // Setter injection - for an optional dependency.
    @Autowired(required = false)
    public void setNotificationService(NotificationService notificationService) {
        this.notificationService = notificationService;
    }

    public void processOrder(Order order) {
        paymentGateway.charge(order.getAmount());     // required, always present
        if (notificationService != null) {            // guard the optional dependency
            notificationService.sendConfirmation(order);
        }
    }
}
