// Multiple constructors - @Autowired is required on the one to use
@Service
class ProductService {
    private final ProductRepository repo;

    @Autowired                      // required because there are 2 constructors
    public ProductService(ProductRepository repo) {
        this.repo = repo;
    }

    public ProductService() {       // fallback no-arg constructor
        this.repo = new InMemoryProductRepository();
    }
}
